SYSTEM_CONTRACT = """You answer ONLY from the <context> block below.
Rules:
- If the context supports an answer, return it and cite the source ids you used.
- If the context does NOT support the answer, set "answer" to null and "refused" to true.
- Never use facts outside <context>. Never guess. Never fill silence.
Return JSON matching this schema exactly."""

CONTRACT_SCHEMA = {
    "type": "object",
    "required": ["answer", "refused", "sources"],
    "properties": {
        "answer":   {"type": ["string", "null"]},
        "refused":  {"type": "boolean"},
        "sources":  {"type": "array", "items": {"type": "string"}},
    },
    "additionalProperties": False,
}

def check_contract(out: dict, retrieved_ids: set[str]) -> list[str]:
    v = []
    if out["refused"] and out["answer"] is not None:
        v.append("refused=true but answer is not null")
    if not out["refused"] and not out["sources"]:
        v.append("answered with zero cited sources (ungrounded)")
    if any(s not in retrieved_ids for s in out["sources"]):
        v.append("cited a source id that was never retrieved")
    return v  # empty list == contract satisfied

