llm-judges-graders.code:
JUDGE_RUBRIC = """You are a strict grader. Grade ONLY against the CONTEXT below.
Do not use outside knowledge. If a claim is not supported by CONTEXT, it fails.

CONTEXT:
{retrieved_context}

QUESTION: {question}
ANSWER: {answer}

Grade each criterion. Return JSON matching the schema exactly:
- grounded: every claim in ANSWER is supported by CONTEXT
- complete: ANSWER covers what QUESTION asked
- refused_correctly: if CONTEXT lacks the answer, ANSWER must refuse
For each: verdict (pass|fail), reason, evidence_span (a quote from CONTEXT)."""

VERDICT_SCHEMA = {
    "type": "object",
    "required": ["grounded", "complete", "refused_correctly", "overall"],
    "properties": {
        "grounded":          {"type": "object", "required": ["verdict", "reason", "evidence_span"]},
        "complete":          {"type": "object", "required": ["verdict", "reason", "evidence_span"]},
        "refused_correctly": {"type": "object", "required": ["verdict", "reason", "evidence_span"]},
        "overall": {"enum": ["pass", "fail"]},
    },
}

def grade(question, answer, retrieved_context, judge_llm):
    prompt = JUDGE_RUBRIC.format(
        retrieved_context=retrieved_context, question=question, answer=answer)
    raw = judge_llm(prompt, response_format=VERDICT_SCHEMA)  # structured output
    verdict = json.loads(raw)                                 # must parse or FAIL
    if verdict["grounded"]["verdict"] == "fail":
        verdict["overall"] = "fail"                            # any ungrounded claim fails
    return verdict

