POLICY = {
    "refuse": ["account_takeover", "self_harm", "illegal"],
    "ground_only": True,      # answer strictly from retrieved sources
    "escalate": ["legal", "medical", "billing_dispute"],
}

def guarded_answer(user_prompt: str) -> dict:
    # 1. INPUT guardrail — runs in code, before the model sees anything
    risk = classify_input(user_prompt)            # jailbreak / PII / policy class
    if risk.category in POLICY["refuse"]:
        return {"action": "refuse", "rule": risk.category, "text": SAFE_REFUSAL}

    # 2. RETRIEVAL grounding gate — no source, no answer
    sources = retrieve(user_prompt, k=5)
    if POLICY["ground_only"] and not sources:
        return {"action": "refuse", "rule": "no_grounded_source", "text": SAFE_REFUSAL}

    draft = llm_answer(user_prompt, sources)

    # 3. OUTPUT guardrail — every claim must trace to a retrieved source
    check = grounding_judge(draft, sources)       # returns supported: bool + spans
    if not check.supported:
        return {"action": "escalate", "rule": "unsupported_claim", "draft": draft}

    return {"action": "answer", "text": draft, "citations": check.spans}

