TOOL_SCHEMA = {
    "name": "search_docs",
    "parameters": {
        "query": {"type": "string", "maxLength": 300},
        "top_k": {"type": "integer", "minimum": 1, "maximum": 20},
    },
    "required": ["query"],
}

def validate_call(name: str, args: dict, user) -> tuple[bool, str]:
    if name != TOOL_SCHEMA["name"]:
        return False, f"unknown tool {name}"
    if "query" not in args:
        return False, "missing required arg: query"
    if len(args["query"]) > 300:
        return False, "query too long (injection/cost guard)"
    if args.get("top_k", 5) > 20:
        return False, "top_k over limit (DoS/cost guard)"
    if name == "refund_order" and not user.can_refund:
        return False, "unauthorized: user lacks refund scope"
    return True, "ok"

def run(name, args, user):
    ok, reason = validate_call(name, args, user)
    if not ok:
        log.warning("BLOCKED", tool=name, reason=reason)
        return {"error": reason}          # repair, do NOT execute
    sources = TOOLS[name](**args)          # execute only after PASS
    return {"sources": sources}            # grounding set for the answer

