import time, json, uuid

# $/1K tokens — the price sheet IS part of your observability config.
PRICE = {"gpt-4o-mini": {"in": 0.00015, "out": 0.0006}}

def price(model, tin, tout):
    p = PRICE[model]
    return round(tin/1000*p["in"] + tout/1000*p["out"], 6)

def answer(query, model="gpt-4o-mini"):
    trace = {"request_id": str(uuid.uuid4()), "model": model, "spans": {}}

    def stage(name, fn):
        t0 = time.perf_counter()
        out = fn()
        trace["spans"][name] = {"latency_ms": round((time.perf_counter()-t0)*1000, 1)}
        return out

    docs   = stage("retrieve", lambda: vector_search(query, k=20))
    top    = stage("rerank",   lambda: rerank(query, docs, k=5))
    result = stage("generate", lambda: llm(model, query, top))
    grounded = stage("guard",  lambda: is_grounded(result.text, top))

    trace["tokens"]  = {"in": result.prompt_tokens, "out": result.completion_tokens}
    trace["cost_usd"] = price(model, result.prompt_tokens, result.completion_tokens)
    trace["grounded"] = grounded
    print(json.dumps(trace))          # -> ship to your trace store / log pipeline
    return result.text if grounded else "I don't have grounded sources for that."

