import json, sys

# 1. Frozen eval set: same queries + expected behavior, versioned in git.
EVAL = json.load(open("eval_set.v3.json"))          # [{q, must_ground|must_refuse}, ...]
BASELINE = json.load(open("baseline.json"))          # last-green scorecard
THRESH = {"grounded": -0.03, "refusal": -0.05, "hallucinations": +2}

def score(system):
    grounded = refused = halluc = 0
    for case in EVAL:
        ans = system(case["q"])                       # returns {grounded, refused, cited}
        if case.get("must_refuse"):
            refused += ans["refused"]                  # correct refusal on unsupported ask
        else:
            grounded += ans["grounded"] and ans["cited"]
        if ans["grounded"] and not ans["cited"]:      # claim with no source == hallucination
            halluc += 1
    n = len(EVAL)
    return {"grounded": grounded / n, "refusal": refused / n, "hallucinations": halluc}

head = score(current_rag_system)                      # HEAD, post-drift
regressions = []
for metric, floor in THRESH.items():
    delta = head[metric] - BASELINE[metric]
    worse = delta < floor if metric != "hallucinations" else delta > floor
    if worse:
        regressions.append(f"{metric}: {BASELINE[metric]} -> {head[metric]} (Δ {delta:+})")

if regressions:
    print("DRIFT GATE FAILED:\n  " + "\n  ".join(regressions)); sys.exit(1)
print("gate green; promote HEAD scorecard to baseline"); json.dump(head, open("baseline.json", "w"))
